class AuthenticationManager {
    int ttl;
    unordered_map<string, int> expiry;
    priority_queue<pair<int, string>, vector<pair<int, string>>, greater<>> pq;

    void cleanup(int now) {
        while (!pq.empty() && pq.top().first <= now) {
            auto [e, tid] = pq.top();
            pq.pop();
            auto it = expiry.find(tid);
            if (it != expiry.end() && it->second == e) expiry.erase(it);
        }
    }
public:
    AuthenticationManager(int timeToLive) : ttl(timeToLive) {}

    void generate(string tokenId, int currentTime) {
        cleanup(currentTime);
        expiry[tokenId] = currentTime + ttl;
        pq.emplace(currentTime + ttl, tokenId);
    }

    void renew(string tokenId, int currentTime) {
        cleanup(currentTime);
        if (expiry.count(tokenId)) {
            expiry[tokenId] = currentTime + ttl;
            pq.emplace(currentTime + ttl, tokenId);
        }
    }

    int countUnexpiredTokens(int currentTime) {
        cleanup(currentTime);
        return expiry.size();
    }
};

