class AuthenticationManager {
    private static class Node {
        final int exp;
        final String id;
        Node(String id, int exp) { this.id = id; this.exp = exp; }
    }

    private final int ttl;
    private final Map<String, Integer> expiry = new HashMap<>();
    private final Queue<Node> pq = new PriorityQueue<>((a, b) -> a.exp - b.exp);

    public AuthenticationManager(int timeToLive) {
        ttl = timeToLive;
    }

    private void cleanup(int now) {
        while (!pq.isEmpty() && pq.peek().exp <= now) {
            Node n = pq.poll();
            Integer cur = expiry.get(n.id);
            if (cur != null && cur == n.exp) expiry.remove(n.id);
        }
    }

    public void generate(String tokenId, int currentTime) {
        cleanup(currentTime);
        expiry.put(tokenId, currentTime + ttl);
        pq.offer(new Node(tokenId, currentTime + ttl));
    }

    public void renew(String tokenId, int currentTime) {
        cleanup(currentTime);
        if (expiry.containsKey(tokenId)) {
            expiry.put(tokenId, currentTime + ttl);
            pq.offer(new Node(tokenId, currentTime + ttl));
        }
    }

    public int countUnexpiredTokens(int currentTime) {
        cleanup(currentTime);
        return expiry.size();
    }
}

