var AuthenticationManager = function(timeToLive) {
    this.ttl = timeToLive;
    this.expiry = new Map();
    this.heap = [];
};

AuthenticationManager.prototype._push = function(node) {
    const h = this.heap;
    h.push(node);
    let i = h.length - 1;
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (h[p].e <= h[i].e) break;
        [h[p], h[i]] = [h[i], h[p]];
        i = p;
    }
};

AuthenticationManager.prototype._pop = function() {
    const h = this.heap;
    const top = h[0];
    const last = h.pop();
    if (h.length) {
        h[0] = last;
        let i = 0;
        for (;;) {
            let m = i;
            const l = 2 * i + 1, r = l + 1;
            if (l < h.length && h[l].e < h[m].e) m = l;
            if (r < h.length && h[r].e < h[m].e) m = r;
            if (m === i) break;
            [h[m], h[i]] = [h[i], h[m]];
            i = m;
        }
    }
    return top;
};

AuthenticationManager.prototype._cleanup = function(now) {
    while (this.heap.length && this.heap[0].e <= now) {
        const node = this._pop();
        if (this.expiry.get(node.id) === node.e) this.expiry.delete(node.id);
    }
};

AuthenticationManager.prototype.generate = function(tokenId, currentTime) {
    this._cleanup(currentTime);
    const e = currentTime + this.ttl;
    this.expiry.set(tokenId, e);
    this._push({ e, id: tokenId });
};

AuthenticationManager.prototype.renew = function(tokenId, currentTime) {
    this._cleanup(currentTime);
    if (this.expiry.has(tokenId)) {
        const e = currentTime + this.ttl;
        this.expiry.set(tokenId, e);
        this._push({ e, id: tokenId });
    }
};

AuthenticationManager.prototype.countUnexpiredTokens = function(currentTime) {
    this._cleanup(currentTime);
    return this.expiry.size;
};
